function roCard({
  id, stage, grade, topic, unitTitle, title, enTitle,
  statement, formula, worked, practice, answers, mistake, source, manualExample
}) {
  return Object.freeze({
    id,
    subject: 'math',
    country: 'RO',
    stage,
    grade: String(grade),
    topic,
    unitTitle,
    title,
    enTitle,
    statement,
    formula,
    worked,
    practice,
    answers,
    mistake,
    source,
    manualExample: manualExample || RO_FULL_MATH_SOURCES.manualsPortal,
    sourceStatus: 'national-framework-aligned',
    curriculumCompletion: 'partial-source-review'
  });
}

