function buildRomaniaLessonsMap() {
  const map = {};
  const add = (stage, row) => {
    const [grade, topic, unitTitle, title, enTitle, statement, formula, worked, practice, answers, mistake] = row;
    const key = `${stage}|${grade}|${topic}`;
    if (!map[key]) map[key] = [];
    const idx = String(map[key].length + 1).padStart(2, '0');
    const source = stage === 'primary'
      ? (grade === '1' || grade === '2' ? RO_FULL_MATH_SOURCES.primary12 : RO_FULL_MATH_SOURCES.primary34)
      : stage === 'intermediate'
        ? (grade === '9' ? RO_FULL_MATH_SOURCES.lycee9_2026 : RO_FULL_MATH_SOURCES.lycee10_12)
        : RO_FULL_MATH_SOURCES.universityBologna;
    map[key].push(roCard({
      id: `math-ro-2026-${stage}-${grade}-${topic}-${idx}`,
      stage,
      grade,
      topic,
      unitTitle,
      title,
      enTitle,
      statement,
      formula,
      worked,
      practice,
      answers,
      mistake,
      source
    }));
  };
  for (const r of RO_PRIMARY_ROWS) add('primary', r);
  for (const r of RO_UPPER_ROWS) add('intermediate', r);
  for (const r of RO_UNIVERSITY_ROWS) add('advanced', r);
  return Object.freeze(map);
}

export const ROMANIA_FULL_TRACK_LESSONS = buildRomaniaLessonsMap();

export function romaniaMathGapLessons({ stage, grade, topic } = {}) {
  const st = stage === 'beginner' ? 'primary' : stage === 'medium' ? 'intermediate' : String(stage || '');
  return ROMANIA_FULL_TRACK_LESSONS[`${st}|${String(grade || '')}|${String(topic || '')}`] || [];
}
